def test_a_backslash_in_a_comment_does_not_swallow_the_newline(self):
    """C1 from the adversarial review of the segmentation change, named so that
    reverting the `in_comment` flag fails a test which states the payload. Both modes:
    the blocklist is not gated on safe_mode, and this was ALLOW in both."""
    for validator in (SAFE, UNSAFE):
        ok, reason = validator.validate('echo #\\\nrm -rf /')
        assert not ok, f"comment + line continuation hid a blocked command ({reason})"

